<?php
 namespace Pterodactyl\Jobs\Dezerx; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Queue\SerializesModels; use Illuminate\Support\Facades\Http; use Illuminate\Support\Facades\Log; use Pterodactyl\Services\Dezerx\Staff\Staff; use Throwable; class SendStaffWebhook implements ShouldQueue { use Dispatchable; use InteractsWithQueue; use Queueable; use SerializesModels; public int $tries = 3; public int $timeout = 15; public function __construct(private array $payload) { } public function backoff(): array { return [10, 60]; } public function handle(): void { $url = Staff::webhookUrl(); if ($url === null) { return; } try { $response = Http::withOptions(['allow_redirects' => false]) ->withHeaders(['Content-Type' => 'application/json']) ->timeout(5) ->connectTimeout(5) ->post($url, $this->payload); if ($response->status() === 429 || $response->serverError()) { $this->release(30); } } catch (Throwable $exception) { Log::warning('A support staff webhook could not be delivered.', ['message' => $exception->getMessage()]); } } } 